/* Drawings use the exact selected mesh. No independently authored plan or section. */
async function OBTPDownloadPDF(model,mesh,blocks,state,palette){
 const makeCanvas=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c;};
 const pages=[],L=model.plan.length,W=model.plan.width||7.2;
 function page(title,subtitle){const c=makeCanvas(1684,1190),x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#242629';x.font='36px Arial';x.fillText('obtp. / architecture',70,78);x.font='28px Arial';x.fillText(title,70,140);x.font='20px Arial';x.fillStyle='#666';x.fillText(subtitle,70,177);x.fillText(`${model.configuration.bedrooms} bedrooms · ${model.configuration.workspace?'Workspace included':'No separate workspace'} · ${L.toFixed(1)} × ${W.toFixed(1)} m · ${(L*W).toFixed(1)} m² footprint`,70,1065);x.font='18px Arial';x.fillText(`Model ${model.id} · Palette ${state.palette} · Architecture study, not construction documentation`,70,1100);x.fillText('Dimensions and geometry are provisional. Roof build-up and connections are not resolved.',70,1130);pages.push(c);return[c,x];}
 let [c,x]=page('01 / Axonometric','Selected model / exterior');const view=makeCanvas(1480,800),v=view.getContext('2d'),data=v.createImageData(1480,800);data.data.set(OBTPMeshRenderer.raster(mesh,{L,W,appearance:'colour',palette},1480,800,45,false));v.putImageData(data,0,0);x.drawImage(view,102,205);
 [c,x]=page('02 / Floor plan','Horizontal model section at 1.10 m / black wall fills / no shadows');const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');Object.defineProperty(svg,'clientWidth',{value:1480});OBTPPlanRenderer.render(svg,model,mesh,blocks,{contrast:'soft',room:''});svg.innerHTML=svg.innerHTML.replace(/<polygon data-room="[^"]*"[^>]*\/>/g,'');svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','1480');svg.setAttribute('height','410');const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});x.drawImage(img,102,370);}finally{URL.revokeObjectURL(url);}
 // Transverse cut through the social space. Transform X into the cut axis,
 // preserving Y and Z for the section drawing.
 const cut=model.architecture?L-model.architecture.social/2:2.25;
 [c,x]=page('03 / Transverse section',`Actual mesh intersection at x = ${cut.toFixed(2)} m / looking along the house`);
 const maxZ=Math.max(...mesh.objects.flatMap(o=>o.vertices.map(v=>v[2]))),s=Math.min(1250/W,700/maxZ),ox=(1684-W*s)/2,oy=950;
 const line=pts=>{x.beginPath();pts.forEach((p,i)=>i?x.lineTo(ox+p[0]*s,oy-p[1]*s):x.moveTo(ox+p[0]*s,oy-p[1]*s));};
 for(const o of mesh.objects){if(['site','detail'].includes(o.kind))continue;const transformed={...o,vertices:o.vertices.map(([a,b,c])=>[b,c,a])};let loops;try{loops=OBTPPlanRenderer.section(transformed,cut);}catch{loops=null;}
 if(loops){for(const loop of loops){line(loop);x.closePath();x.fillStyle=['wall','partition','floor','base'].includes(o.kind)?'#090909':'#f2f2f2';x.fill();x.strokeStyle='#777';x.lineWidth=1;x.stroke();}}
 else {x.strokeStyle=o.kind==='roof'?'#222':'#777';x.lineWidth=o.kind==='roof'?2:1;for(const f of o.faces){const pts=[];for(let i=0;i<f.length;i++){const a=o.vertices[f[i]],b=o.vertices[f[(i+1)%f.length]];if((a[0]<cut)!==(b[0]<cut)){const t=(cut-a[0])/(b[0]-a[0]);pts.push([a[1]+t*(b[1]-a[1]),a[2]+t*(b[2]-a[2])]);}}if(pts.length===2){line(pts);x.stroke();}}}}
 x.font='18px Arial';x.fillStyle='#666';x.fillText('Roof shown as the existing model surface; no thickness has been invented.',70,220);
 const bytes=OBTPImagePDF(pages.map(c=>({w:c.width,h:c.height,jpeg:Uint8Array.from(atob(c.toDataURL('image/jpeg',.95).split(',')[1]),v=>v.charCodeAt(0))})));
 const download=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=document.createElement('a');a.href=download;a.download=`OBTP-${model.id}-${state.palette}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(download),30000);return bytes;
}
function OBTPImagePDF(images){const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const put=a=>{if(typeof a==='string')a=encoder.encode(a);chunks.push(a);length+=a.length;};const obj=(id,content)=>{offsets[id]=length;put(`${id} 0 obj\n`);put(content);put('\nendobj\n');};put('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${images.length} /Kids [${images.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);images.forEach((im,i)=>{const id=3+i*3;obj(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);offsets[id+1]=length;put(`${id+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${im.w} /Height ${im.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${im.jpeg.length} >>\nstream\n`);put(im.jpeg);put('\nendstream\nendobj\n');const content='q 842 0 0 595 0 0 cm /Im Do Q';obj(id+2,`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);});const start=length;put(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);offsets.slice(1).forEach(o=>put(String(o).padStart(10,'0')+' 00000 n \n'));put(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);const out=new Uint8Array(length);let at=0;chunks.forEach(c=>{out.set(c,at);at+=c.length;});return out;}
